-- ============================================================
-- 37_import_crew_time.sql
--
-- Imports the Team Time Tracker: 448 crew time rows, Feb-Sep 2026,
-- for Carlos, Tito, Roberto, Ronald, Avelino, Edy, Salvador. Each row
-- is one person on one job on one day, matched to a job by client
-- name (repeat clients split by date). ~4,245 hours across 45 jobs.
--
-- job_financials already prefers logged hours over a typed Labor
-- figure, so after this runs those 45 jobs cost labor at each
-- person's crew rate x hours. The old reconciled Labor cost rows are
-- left in place but ignored while hours are present.
--
-- NOTE: the Supabase SQL editor truncates a paste this large (it
-- stopped at ~168 rows). If the verify below does not say PASS, run
-- the 6 split files 37_part1.sql through 37_part6.sql instead -
-- each is a self-contained, re-runnable slice by job.
--
-- Re-runnable: deletes its own prior import first (entered_by tag).
-- 'Jayme' (2 rows, 15h, no matching job) is intentionally skipped.
-- Run any time. Safe to re-run.
-- ============================================================

delete from time_entries where entered_by = 'ttt-import';


-- verify: expect 448 imported rows across 45 jobs
select
  (select count(*) from time_entries where entered_by = 'ttt-import') as imported_rows,
  (select count(distinct job_id) from time_entries where entered_by = 'ttt-import') as jobs_touched,
  (select round(sum(hours)) from time_entries where entered_by = 'ttt-import') as total_hours,
  case when (select count(*) from time_entries where entered_by = 'ttt-import') = 448
       then 'PASS' else 'FAIL - run 37_part1..6 instead' end as result;

